/**
 * Everything a native module needs to work on a device another library owns: the contract version, the
 * function table and the instance / adapter / device / queue handles. Filled from any IWebGpuDeviceSource.
 *
 * The handles are BORROWED: valid while the owner keeps its device (until the owner is disposed); reading them
 * takes no reference. A module that keeps a handle longer calls its *AddRef and later *Release on it.
 */
typedef struct WGPUCodebrixDeviceHandoff {
    /** sizeof(WGPUCodebrixDeviceHandoff) as filled by the producer. */
    uint32_t size;
    /** The layout version of this struct (WGPU_CODEBRIX_DEVICE_HANDOFF_VERSION). */
    uint32_t version;
    /** WGPU_CODEBRIX_API_VERSION of the loaded library; refuse the hand-off when it differs from the one the module was built against. */
    uint32_t apiVersion;
    /** The backend the device runs on (WGPUBackendType_Undefined without a device). */
    WGPUBackendType backend;
    /** Bit WGPU_CODEBRIX_DEVICE_HANDOFF_FLAG_UNCAPTURED_ERROR_HANDLER: the device has an uncaptured-error handler. Without it any uncaptured validation error ENDS THE PROCESS - keep risky work inside error scopes. */
    uint32_t flags;
    /** Zero. */
    uint32_t reserved;
    /** The function table of the loaded library (process lifetime; never free it). */
    WGPUCodebrixProcTable const * procs;
    /** The instance, or NULL when the owner has none. */
    WGPUInstance instance;
    /** The adapter, or NULL when the owner has none. */
    WGPUAdapter adapter;
    /** The device; NULL means no usable device. */
    WGPUDevice device;
    /** The queue the owner submits to. */
    WGPUQueue queue;
} WGPUCodebrixDeviceHandoff;

/**
 * One frame's target for a native module: the texture another library owns (IWebGpuTextureTarget) and the
 * command encoder of its open pass.
 *
 * The handles are BORROWED for the pass only (from BeginWebGpuPass to EndWebGpuPass): record every command
 * that touches the texture into commandEncoder, on the thread that opened the pass, close your own render /
 * compute passes before returning, and never finish, submit or release the encoder.
 */
typedef struct WGPUCodebrixFrameHandoff {
    /** sizeof(WGPUCodebrixFrameHandoff) as filled by the producer. */
    uint32_t size;
    /** The layout version of this struct (WGPU_CODEBRIX_FRAME_HANDOFF_VERSION). */
    uint32_t version;
    /** The texture's format (pipelines must target it). */
    WGPUTextureFormat format;
    /** The width in pixels. */
    uint32_t width;
    /** The height in pixels. */
    uint32_t height;
    /** The texture's sample count (pipelines and depth attachments must match). */
    uint32_t sampleCount;
    /** The texture's usage flags. */
    WGPUTextureUsage usage;
    /** The texture. */
    WGPUTexture texture;
    /** A default view of the texture (a render attachment). */
    WGPUTextureView textureView;
    /** The encoder of the open pass (from BeginWebGpuPass); NULL when no pass is open - then record nothing. */
    WGPUCommandEncoder commandEncoder;
} WGPUCodebrixFrameHandoff;

